import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.CNDWyMYS.js";const k=JSON.parse('{"title":"Types of rocks","description":"","frontmatter":{},"headers":[],"relativePath":"types_of_rocks.md","filePath":"types_of_rocks.md"}'),s={name:"types_of_rocks.md"};function c(i,e,n,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="types-of-rocks" tabindex="-1">Types of rocks <a class="header-anchor" href="#types-of-rocks" aria-label="Permalink to &quot;Types of rocks&quot;">​</a></h1><p>A <strong>rock</strong> is a bundle containing a specification file (called a &quot;rockspec&quot;) and files providing Lua modules.</p><p>A <strong><a href="./rockspec_format.html">rockspec</a></strong> is a Lua file containing a series of assignments to variables that provide various information about the rock, such as description metadata, dependency relations and build rules. Rocks are created from rockspecs.</p><p>When packed, a rock is an archive file in ZIP format, with the .rock filename extension. When installed, a rock is unpacked into a directory in the local rocks repository.</p><p>There are several types of rocks, and when packed they are identified by their filename extensions. These are:</p><ul><li><p>Source rocks (<code>.src.rock</code>): these contain the rockspec and the source code for the Lua modules provided by the rock. When installing a source rock, the source code needs to be compiled.</p></li><li><p>Binary rocks (<code>_.system-arch_.rock</code>: <code>.linux-x86.rock, .macosx-powerpc.rock</code>): these contain the rockspec and modules in compiled form. Modules written in Lua may be in source .lua format, but modules compiled as C dynamic libraries are compiled to their platform-specific format.</p></li><li><p>Pure-Lua rocks (<code>.all.rock</code>): these contain the rockspec and the Lua modules they provide in .lua format. These rocks are directly installable without a compilation stage and are platform-independent.</p></li></ul>',6)])])}const u=o(s,[["render",c]]);export{k as __pageData,u as default};
